lib = '''def background(grid):
    """The most common color in the grid."""
    cnt = {}
    for row in grid:
        for v in row: cnt[v] = cnt.get(v, 0) + 1
    return max(cnt, key=cnt.get)

def dots(grid, bg=None):
    """Every non-background cell as (row, col, color)."""
    if bg is None: bg = background(grid)
    return [(i, j, grid[i][j]) for i in range(len(grid)) for j in range(len(grid[0])) if grid[i][j] != bg]

def aligned(a, b):
    """True if two cells share a row, column, or diagonal (8 directions)."""
    dr, dc = b[0] - a[0], b[1] - a[1]
    return dr == 0 or dc == 0 or abs(dr) == abs(dc)

def seg(a, b):
    """The straight cells from cell a to cell b (8 directions)."""
    dr, dc = b[0] - a[0], b[1] - a[1]
    n = max(abs(dr), abs(dc))
    sr = dr // n if n else 0
    sc = dc // n if n else 0
    return [(a[0] + k * sr, a[1] + k * sc) for k in range(n + 1)]

def draw_lines(grid, pairs):
    """Color each cell of the given (cells, color) segments that is background."""
    bg = background(grid)
    out = [row[:] for row in grid]
    for cells, c in pairs:
        for (r, w) in cells:
            if out[r][w] == bg: out[r][w] = c
    return out

def full_span(r, c, dr, dc, h, w):
    """Every cell of the straight line through (r, c) with step (dr, dc), across the whole grid."""
    n = max(abs(dr), abs(dc))
    dr, dc = dr // n if n else 0, dc // n if n else 0
    cells = set()
    rr, cc = r, c
    while 0 <= rr < h and 0 <= cc < w:
        cells.add((rr, cc)); rr += dr; cc += dc
    rr, cc = r - dr, c - dc
    while 0 <= rr < h and 0 <= cc < w:
        cells.add((rr, cc)); rr -= dr; cc -= dc
    return sorted(cells)
