def extract_funcs(s):
    """Extract full top-level def sources from a decoded string."""
    out = {}
    lines = s.split('\n')
    i = 0
    while i < len(lines):
        m = re.match(r'(?:>>> |print\()?def (\w+)\(', lines[i])
        if not m:
            # also handle def inside code with leading spaces (but top-level only)
            m2 = re.match(r'def (\w+)\(', lines[i])
            m = m2
        if m:
            name = m.group(1)
            body = [lines[i]]
            i += 1
            while i < len(lines) and (lines[i].startswith((' ', '\t')) or lines[i].strip() == ''):
                # stop if blank line followed by non-indented def-ish line
                if lines[i].strip() == '':
                    nxt = i+1
                    if nxt < len(lines) and lines[nxt] and not lines[nxt][0].isspace() and not lines[nxt].startswith('def '):
                        break
                    body.append(lines[i]); i += 1
                else:
                    body.append(lines[i]); i += 1
            src = '\n'.join(body).rstrip()
            if name not in out or len(src) > len(out[name]):
                out[name] = src
        else:
            i += 1
    return out

